const companyName = $json['Company Name'] || '';
const anchor = ($json['Anchor'] || companyName).toString();
const sector = $json['Sector'] || '';
const website = $json['Website URL'] || '';
const query = encodeURIComponent(anchor + ' when:2d');
const rssUrl = 'https://news.google.com/rss/search?q=' + query + '&hl=en-US&gl=US&ceid=US:en';
return { json: { companyName, anchor, sector, website, rssUrl } };

const targets = $('Get Targets').all();
const responses = $input.all();
const cutoff = Date.now() - (48 * 60 * 60 * 1000);
const out = [];
for (let i = 0; i < responses.length; i++) {
  const t = (targets[i] && targets[i].json) ? targets[i].json : {};
  const companyName = t['Company Name'] || '';
  const anchor = t['Anchor'] || '';
  const sector = t['Sector'] || '';
  const xml = (responses[i].json.data || '').toString();
  const blocks = xml.match(new RegExp('<item>[^]*?</item>', 'g')) || [];
  const getTag = (block, tag) => {
    const m = block.match(new RegExp('<' + tag + '>([^]*?)</' + tag + '>'));
    if (!m) return '';
    let v = m[1];
    v = v.split('<![CDATA[').join('').split(']]>').join('');
    return v.trim();
  };
  let count = 0;
  for (const block of blocks) {
    if (count >= 6) break;
    const title = getTag(block, 'title');
    const link = getTag(block, 'link');
    const pubDate = getTag(block, 'pubDate');
    let description = getTag(block, 'description');
    description = description.replace(new RegExp('<[^>]+>', 'g'), ' ').replace(new RegExp('  +', 'g'), ' ').trim();
    const pubMs = pubDate ? new Date(pubDate).getTime() : 0;
    if (pubMs && pubMs < cutoff) continue;
    if (!title || !link) continue;
    out.push({ json: { companyName, anchor, sector, title, url: link, pubDate, description } });
    count++;
  }
}
return out;
